import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.CXXr-9tD.js";var c=JSON.parse(`{"title":"The board","description":"","frontmatter":{},"headers":[],"relativePath":"board.md","filePath":"pages/board.md"}`),l={name:`board.md`};function u(a,c,l,u,d,f){let p=e(`BoardDemo`);return s(),n(`div`,null,[c[0]||=o(`h1`,{id:`the-board`,tabindex:`-1`},[r(`The board `),o(`a`,{class:`header-anchor`,href:`#the-board`,"aria-label":`Permalink to “The board”`},`​`)],-1),c[1]||=o(`p`,null,[r(`A graph is topology. A board is topology plus placed items: a section, a fence, a sticky, an SVG — each one an item with a position, an item whose identity is the `),o(`code`,null,`locatorHash`),r(` of the address it came from. Drag the cards below. Then press `),o(`em`,null,`Insert a block above the fence`),r(` and watch what does not move.`)],-1),i(p),c[2]||=t(`<h2 id="what-you-are-looking-at" tabindex="-1">What you are looking at <a class="header-anchor" href="#what-you-are-looking-at" aria-label="Permalink to “What you are looking at”">​</a></h2><p>Each card is a block of a markdown document, projected into items by <code>boardFromDocuments</code>, exactly as <code>markdownGraph</code> projects the same document into nodes. The card&#39;s <code>itemId</code> is its address&#39;s <code>locatorHash</code>; <code>blockId</code> under it is <code>section/ordinal</code>.</p><p>Dragging writes a placement. Press <em>Insert a block above the fence</em> and the document is re-read: the fence&#39;s ordinal shifts, so its <code>blockId</code> shifts, so its <code>locatorHash</code> shifts — and the card is still in the same place, because <code>reconcileBoard</code> re-anchors the item and carries the placement onto the new id. An item it cannot find is reported as an orphan and dropped, never silently moved.</p><h2 id="what-this-page-is-not" tabindex="-1">What this page is not <a class="header-anchor" href="#what-this-page-is-not" aria-label="Permalink to “What this page is not”">​</a></h2><p>Positions here live in this browser&#39;s storage, because a static page cannot write a file. The board the repository writes is <code>&lt;document&gt;.board.json</code> beside its document, written through a temp file and a rename so a reader never meets half of one, and read only when <code>validateBoard</code> accepts it — <code>pnpm --filter @hafley66/grapht run smoke:board</code> runs that end to end, and <code>packages/grapht/tests/4_board</code> holds it to account.</p><p>An item with no placement is a young board, not a broken one: it draws at the stack position <code>boardFrame</code> gives it.</p><h2 id="what-is-still-missing" tabindex="-1">What is still missing <a class="header-anchor" href="#what-is-still-missing" aria-label="Permalink to “What is still missing”">​</a></h2><p>The item renderers and the file write/read are landed. The <em>live</em> surface — a host that turns pointer gestures into a movement journal and reloads the board from its file — is the phase this page anticipates: see <a href="./roadmap">Feature status</a>.</p>`,8)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};